body{margin:0;background:linear-gradient(180deg,var(--bg),#0b0d18);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.wrap{max-width:1100px;margin:0 auto;padding:18px}
.hdr{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
h1{font-size:20px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
