const groups = [
  {
    title: 'Exceptional circumflexes',
    examples: [
      ['ὀρφῶς', 'Circumflex on the last syllable', 'Compare ὄρφος. The common form has its accent on the first syllable.'],
      ['λαγῶς', 'Circumflex on the last syllable', 'Compare λαγός. The common form has an acute on the last syllable.']
    ]
  },
  {
    title: 'Alternative endings and contraction',
    examples: [
      ['τυφῶς', 'Circumflex on the last syllable', 'Herodian sets this form apart because it can also end in -ν: τυφῶν.'],
      ['ταὧς', 'Circumflex on the last syllable', 'Herodian gives the alternate ending ταὧν and rejects derivation from ταός, which he says is uncommon in Greek.'],
      ['Μανεθῶς', 'Circumflex on the last syllable', 'Herodian pairs the -ς form with Μανεθῶν, which ends in -ν.'],
      ['Τηλεβῶς', 'Circumflex on the last syllable', 'Herodian derives this form by contraction from Τηλεβόας.']
    ]
  },
  {
    title: 'Attic forms without common counterparts',
    examples: [
      ['κορώνεως', 'Acute on the antepenult', 'This plant name belongs to the Attic group accented on the third syllable from the end.'],
      ['φιβάλεως', 'Acute on the antepenult', 'This plant name belongs to the Attic group accented on the third syllable from the end.'],
      ['ἱέρεως', 'Acute on the antepenult', 'Herodian includes ἱέρεως, “the priest,” in this Attic group.']
    ]
  },
  {
    title: 'Persian or Egyptian forms',
    examples: [
      ['Φάργως', 'Acute on the penult', 'Herodian accents these forms on the second syllable from the end.'],
      ['Ἰνάρως', 'Acute on the penult', 'Herodian gives this king’s name as an example of an accent on the second syllable from the end.'],
      ['Παραμίζως', 'Acute on the penult', 'Herodian gives this eunuch’s name as an example of an accent on the second syllable from the end.'],
      ['Σαβάκως', 'Acute on the penult', 'Herodian accents these forms on the second syllable from the end.']
    ]
  },
  {
    title: 'Feminine forms with a short penult',
    examples: [
      ['Κέως', 'Acute on the penult', 'Herodian lists this name among feminine forms with a short penult and an accent before the final syllable.'],
      ['Τέως', 'Acute on the penult', 'The name of the Ionian city illustrates Herodian’s group of feminine forms with a short penult.']
    ]
  }
];

const input = document.querySelector('#word');
const readingWord = document.querySelector('#reading-word');
const accent = document.querySelector('#accent');
const explanation = document.querySelector('#explanation');
const examples = new Map();
const buttons = new Map();

function key(text) {
  return text.trim().normalize('NFD').replace(/\p{M}/gu, '')
    .toLowerCase().replace(/σ$/, 'ς');
}

function show(example, message) {
  const [word, accentText, note] = example || ['', '', message];
  readingWord.textContent = word;
  accent.textContent = accentText;
  explanation.textContent = note;
  for (const [exampleWord, button] of buttons) {
    button.setAttribute('aria-pressed', String(exampleWord === word));
  }
}

function lookUp() {
  const search = key(input.value);
  if (!search) {
    show(null, 'Choose a Greek example to see its accent and explanation.');
    return;
  }
  show(examples.get(search), 'No example matches. Choose one of the listed forms.');
}

const list = document.querySelector('#groups');
for (const group of groups) {
  const section = document.createElement('section');
  const heading = document.createElement('h3');
  heading.textContent = group.title;
  const choices = document.createElement('div');
  choices.className = 'examples';
  section.append(heading, choices);
  for (const example of group.examples) {
    const [word] = example;
    const button = document.createElement('button');
    button.type = 'button';
    button.lang = 'grc';
    button.textContent = word;
    button.addEventListener('click', () => {
      input.value = word;
      show(example);
    });
    choices.append(button);
    examples.set(key(word), example);
    buttons.set(word, button);
  }
  list.append(section);
}

document.querySelector('#find').addEventListener('click', lookUp);
document.querySelector('#clear').addEventListener('click', () => {
  input.value = '';
  lookUp();
  input.focus();
});
input.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') lookUp();
});
lookUp();

