const $ = (selector) => document.querySelector(selector);
const input = $('#inp');
const controls = {
  nt: $('#tglNt'),
  feminine: $('#tglFeminine'),
  month: $('#tglMonth')
};

const explanations = {
  compound: 'Masculine compounds in -φων declined with -ντ- take a final circumflex.',
  phon: 'Herodian gives these masculine forms in -φων an earlier accent when they do not decline with -ντ-.',
  feminine: 'Herodian treats this named example as feminine and gives it a final acute.',
  typhon: 'Herodian gives Τυφῶν a final circumflex and also gives the alternative ending Τυφώς.',
  chon: 'Herodian gives disyllabic masculine forms in -χων an earlier accent, excluding month names.',
  glechon: 'Herodian expects an earlier accent for γλήχων. He specifies a final acute for a feminine variant with β.',
  month: 'Herodian gives this Egyptian month name a final acute.',
  polusperchon: 'Herodian gives Πολυσπερχῶν a final circumflex and says it declines with -ντ-.',
  biston: 'Herodian gives the ethnic adjective Βιστών, declined with ο, a final acute.',
  plataniston: 'Herodian gives the river name Πλατανιστών a final acute.'
};
const categories = {
  compound: 'circumflex',
  phon: 'earlier',
  feminine: 'acute',
  typhon: 'circumflex',
  chon: 'earlier',
  glechon: 'earlier',
  month: 'acute',
  polusperchon: 'circumflex',
  biston: 'acute',
  plataniston: 'acute'
};
const examples = [
  ['Ἀγλαοφῶν', 'compound'], ['Ξενοφῶν', 'compound'], ['Δημοφῶν', 'compound'],
  ['Τρύφων', 'phon'], ['Σόφων', 'phon'],
  ['Κολοφών', 'feminine'], ['Τολοφών', 'feminine'], ['κατηφών', 'feminine'],
  ['Τυφῶν', 'typhon'],
  ['Βρύχων', 'chon'], ['Τύχων', 'chon'], ['Σπέρχων', 'chon'], ['Τάρχων', 'chon'],
  ['γλήχων', 'glechon'], ['παχών', 'month'], ['Πολυσπερχῶν', 'polusperchon'],
  ['Βιστών', 'biston'], ['Πλατανιστών', 'plataniston']
];
const tone = /[\u0300\u0301\u0342]/g;
const vowels = /^[αεηιουω]/i;
const diphthong = /^(αι|αυ|ει|ευ|ηυ|οι|ου|υι)$/i;
const labels = {
  circumflex: 'final circumflex',
  acute: 'final acute',
  earlier: 'earlier accent',
  unknown: 'no rule here'
};

function letters(word) {
  return word.normalize('NFD').replace(tone, '').normalize('NFC');
}

function key(word) {
  return word.trim().normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
}

function vowelTargets(word) {
  const targets = [];
  const clusters = [...word.normalize('NFD').matchAll(/\p{L}\p{M}*/gu)];
  let previousVowel = null;
  for (const match of clusters) {
    const [cluster] = match;
    if (!vowels.test(cluster)) {
      previousVowel = null;
      continue;
    }
    const joinsPrevious = previousVowel &&
      previousVowel.index + previousVowel[0].length === match.index &&
      diphthong.test(previousVowel[0][0] + cluster[0]) &&
      !cluster.includes('\u0308') && !previousVowel[0].includes('\u0345');
    const target = { label: cluster, index: match.index + cluster.length };
    if (joinsPrevious) {
      target.label = previousVowel[0] + cluster;
      targets[targets.length - 1] = target;
      previousVowel = null;
    } else {
      targets.push(target);
      previousVowel = match;
    }
  }
  return targets;
}

function mark(word, target, accent) {
  const nfd = word.normalize('NFD');
  return (nfd.slice(0, target.index) + accent + nfd.slice(target.index)).normalize('NFC');
}

function exampleFlags(group) {
  return {
    nt: group === 'compound' || group === 'polusperchon',
    feminine: group === 'feminine',
    month: group === 'month'
  };
}

function findExample(word) {
  return examples.find(([form]) => key(form) === key(word));
}

function readFlags() {
  return Object.fromEntries(Object.entries(controls).map(([name, control]) => [name, control.checked]));
}

function setExampleFlags() {
  const group = findExample(input.value)?.[1];
  const flags = exampleFlags(group);
  for (const [name, control] of Object.entries(controls)) control.checked = flags[name];
}

function chooseRule(word, targets, flags) {
  const example = findExample(word);
  if (example) {
    const [form, group] = example;
    const defaults = exampleFlags(group);
    if (Object.keys(flags).every((name) => flags[name] === defaults[name])) {
      return { category: categories[group], why: explanations[group], form };
    }
    if (['typhon', 'biston', 'plataniston', 'glechon'].includes(group)) {
      return { category: categories[group], why: explanations[group], form };
    }
  }
  const ending = key(word);
  if (ending.endsWith('φων') && !flags.feminine && !flags.month) {
    return flags.nt
      ? { category: 'circumflex', why: explanations.compound }
      : { category: 'earlier', why: 'This rule leaves the accent before the final syllable. Compare Τρύφων for the placement in a named example.' };
  }
  if (ending.endsWith('χων') && targets.length === 2 && !flags.feminine && !flags.month && !flags.nt) {
    return { category: 'earlier', why: explanations.chon };
  }
  return { category: 'unknown', why: 'This passage gives no prediction for these settings. Try a named example.' };
}

function renderTargets(word, targets, category) {
  $('#targets').replaceChildren();
  const last = targets.slice(-3);
  const names = ['antepenult', 'penult', 'ult'].slice(3 - last.length);
  last.forEach((target, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'tgt';
    button.lang = 'grc';
    button.dataset.which = names[index];
    button.setAttribute('aria-pressed', 'false');
    button.textContent = target.label.normalize('NFC');
    const tag = document.createElement('span');
    tag.className = 'tag';
    tag.lang = 'en';
    tag.textContent = names[index];
    button.append(tag);
    button.addEventListener('click', () => {
      for (const choice of $('#targets').children) {
        choice.setAttribute('aria-pressed', String(choice === button));
      }
      const accent = category === 'circumflex' && names[index] === 'ult' ? '\u0342' : '\u0301';
      $('#toyForm').textContent = mark(word, target, accent);
    });
    $('#targets').append(button);
  });
}

function analyze() {
  const word = input.value.trim();
  $('#targets').replaceChildren();
  $('#ruleLine').textContent = '—';
  $('#toyForm').textContent = '—';
  $('#decline').textContent = '—';
  if (!word || !/^(?:\p{Script=Greek}\p{M}*)+$/u.test(word.normalize('NFD'))) {
    $('#ruleWhy').textContent = word ? 'Enter one Greek word.' : 'Type a word to begin.';
    return;
  }

  const flags = readFlags();
  const base = letters(word);
  const targets = vowelTargets(base);
  const { category, why, form } = chooseRule(word, targets, flags);
  const final = targets.at(-1);
  let shown = form || word.normalize('NFC');
  if (!form && final && (category === 'acute' || category === 'circumflex')) {
    shown = mark(base, final, category === 'acute' ? '\u0301' : '\u0342');
  }
  if (!form && category === 'earlier') shown = base;
  const badge = document.createElement('span');
  badge.className = 'badge';
  badge.textContent = labels[category];
  $('#ruleLine').textContent = shown + ' ';
  $('#ruleLine').append(badge);
  $('#ruleWhy').textContent = why;
  $('#toyForm').textContent = shown;
  if (flags.nt && category === 'circumflex') {
    $('#decline').textContent = '-ων → -οντος (pattern)';
  }
  renderTargets(base, targets, category);
}

function loadExample(form) {
  input.value = form;
  setExampleFlags();
  analyze();
}

for (const [form, group] of examples) {
  const chip = document.createElement('button');
  chip.type = 'button';
  chip.className = 'chip';
  chip.lang = 'grc';
  chip.textContent = form;
  chip.title = explanations[group];
  chip.addEventListener('click', () => loadExample(form));
  $('#chips').append(chip);
}

input.addEventListener('input', setExampleFlags);
input.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') analyze();
});
$('#btnAnalyze').addEventListener('click', analyze);
$('#btnClear').addEventListener('click', () => {
  input.value = '';
  setExampleFlags();
  analyze();
  input.focus();
});
$('#btnRandom').addEventListener('click', () => {
  loadExample(examples[Math.floor(Math.random() * examples.length)][0]);
});
for (const control of Object.values(controls)) control.addEventListener('change', analyze);
analyze();

original.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1e2238;
  --ink:#eef0ff;
  --muted:#b9bde6;
  --faint:#8b90c7;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --warn:#fbbf24;
  --ok:#34d399;
  --bad:#fb7185;
  --line:rgba(255,255,255,.10);
}
*{box-sizing:border-box}
body{margin:0;background:linear-gradient(180deg,var(--bg),#0b0d18);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.wrap{max-width:1100px;margin:0 auto;padding:18px}
.hdr{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
h1{font-size:20px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px}
.controls{padding:6px 6px 12px 6px;border-bottom:1px solid var(--line)}
.lbl{display:block;color:var(--muted);font-weight:600;margin:0 0 6px 0}
.row{display:flex;gap:10px;flex-wrap:wrap}
.inp{flex:1;min-width:260px;background:#0c0f1d;border:1px solid var(--line);color:var(--ink);padding:10px 12px;border-radius:10px;font-size:16px}
.inp:focus{outline:2px solid rgba(125,211,252,.35);border-color:rgba(125,211,252,.55)}
.btn{background:linear-gradient(180deg,#2b3152,#232846);border:1px solid var(--line);color:var(--ink);padding:10px 12px;border-radius:10px;cursor:pointer;font-weight:650}
.btn:hover{border-color:rgba(125,211,252,.45)}
.btn.ghost{background:transparent}
.toggles{display:flex;gap:14px;flex-wrap:wrap;margin-top:10px}
.chk{color:var(--muted);user-select:none}
.chk input{transform:translateY(1px)}
.help{margin-top:10px;color:var(--muted)}
.help summary{cursor:pointer;color:var(--accent)}
.note{color:var(--faint)}
.out{display:grid;grid-template-columns:1.1fr 1.2fr .9fr;gap:12px;margin-top:12px}
@media (max-width: 980px){.out{grid-template-columns:1fr}}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px}
.card h2{margin:0 0 8px 0;font-size:14px;color:var(--muted);text-transform:uppercase;letter-spacing:.12em}
.big{font-size:22px;font-weight:750;letter-spacing:.2px}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace}
.why{margin-top:6px;color:var(--muted)}
.mini{color:var(--muted);font-size:13px;margin-bottom:8px}
.targets{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 10px 0}
.tgt{border:1px solid var(--line);background:#0c0f1d;color:var(--ink);padding:8px 10px;border-radius:999px;cursor:pointer}
.tgt:hover{border-color:rgba(167,139,250,.55)}
.tgt .tag{color:var(--faint);font-size:12px;margin-left:6px}
.tgt.sel{outline:2px solid rgba(167,139,250,.35);border-color:rgba(167,139,250,.55)}
.row2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media (max-width: 700px){.row2{grid-template-columns:1fr}}
.lbl2{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.12em;margin-bottom:4px}
.decline{color:var(--muted)}
.chips{display:flex;gap:8px;flex-wrap:wrap}
.chip{border:1px solid var(--line);background:#0c0f1d;color:var(--ink);padding:7px 10px;border-radius:999px;cursor:pointer}
.chip:hover{border-color:rgba(125,211,252,.45)}
.small{color:var(--faint);font-size:12.5px;margin-top:12px}
.ftr{padding:10px 2px 0 2px}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);margin-left:8px;font-size:12px;color:var(--muted)}
.bOk{color:var(--ok)}
.bWarn{color:var(--warn)}
.bBad{color:var(--bad)}

original.gadget_js:
const $ = (sel) => document.querySelector(sel);

const examples = [
  {w:"Ἀγλαοφῶν", nt:true, note:"-φων compound + -ντ- → circumflex"},
  {w:"Ξενοφῶν", nt:true, note:"-φων compound + -ντ- → circumflex"},
  {w:"Δημοφῶν", nt:true, note:"-φων compound + -ντ- → circumflex"},
  {w:"Τρύφων", nt:false, note:"-φων not -ντ- → grave"},
  {w:"Σόφων", nt:false, note:"-φων not -ντ- → grave"},
  {w:"Κολοφών", fem:true, note:"noted as acute (as feminine)"},
  {w:"Τολοφών", fem:true, note:"noted as acute (as feminine)"},
  {w:"κατηφών", fem:true, note:"noted as acute (as feminine)"},
  {w:"Τυφῶν", nt:false, note:"circumflex; also Τυφώς"},
  {w:"Βρύχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"Τύχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"Σπέρχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"Τάρχων", nt:false, note:"disyllabic -χων masc → grave"},
  {w:"παχών", month:true, note:"month-name exception → acute"},
  {w:"Πολυσπερχῶν", nt:true, note:"-χων + -ντ- → circumflex (named)"},
  {w:"Βιστών", nt:false, note:"ethnic declined with ο → acute"},
  {w:"Πλατανιστών", nt:false, note:"acute (named)"}
];

// --- Polytonic helpers (best-effort) ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  macron: "\u0304",
  breve: "\u0306",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345"
};

const greekVowels = new Set(["α","ε","η","ι","ο","υ","ω","Α","Ε","Η","Ι","Ο","Υ","Ω"]);

function stripAccents(s){
  // Remove combining diacritics; keep base letters.
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
}

function lastVowelIndexNFD(nfd){
  // Find index in NFD string of the last vowel base char.
  for(let i=nfd.length-1;i>=0;i--){
    const ch = nfd[i];
    if(greekVowels.has(ch)) return i;
  }
  return -1;
}

function applyAccentToLastVowel(word, accent){
  const nfd = word.normalize('NFD');
  const i = lastVowelIndexNFD(nfd);
  if(i<0) return word;

  // Remove existing accent marks from that vowel cluster (acute/grave/circumflex)
  // by deleting combining marks immediately after the vowel.
  let out = "";
  for(let k=0;k<nfd.length;k++){
    const ch = nfd[k];
    if(k===i){
      out += ch;
      // skip following combining marks, but keep non-accent diacritics except we will re-add them.
      // We'll collect them and re-add all except accent marks.
      let j=k+1;
      let kept = "";
      while(j<nfd.length && /[\u0300-\u036f]/.test(nfd[j])){
        const m = nfd[j];
        if(m!==combining.acute && m!==combining.grave && m!==combining.circumflex){
          kept += m;
        }
        j++;
      }
      out += kept + combining[accent];
      k = j-1;
    } else {
      out += ch;
    }
  }
  return out.normalize('NFC');
}

function endsWithAny(s, arr){
  return arr.some(x => s.endsWith(x));
}

function guessRule(wordRaw, flags){
  const word = wordRaw.trim();
  const base = stripAccents(word);
  const lower = base.toLowerCase();

  // Identify ending class (very rough)
  const isPhon = endsWithAny(lower, ["φων"]);
  const isChon = endsWithAny(lower, ["χων"]);
  const isOn = !isPhon && !isChon && endsWithAny(lower, ["ων"]);
  const isBiston = lower === "βιστων";
  const isPlataniston = lower === "πλατανιστων";
  const isTyphon = lower === "τυφων";
  const isGlechon = lower === "γληχων";

  // Determine accent expectation on final syllable per passage.
  // We'll output: {accent: 'acute'|'grave'|'circumflex'|null, label, why, confidence}
  let accent = null;
  let why = "";
  let conf = "medium";

  if(isPlataniston){
    accent = "acute";
    why = "Named in the passage as acute: Πλατανιστών.";
    conf = "high";
  } else if(isBiston){
    accent = "acute";
    why = "Herodian: Βιστών (ethnic declined with ο) is acute.";
    conf = "high";
  } else if(isTyphon){
    accent = "circumflex";
    why = "Herodian: Τυφῶν is circumflex (and also said Τυφώς).";
    conf = "high";
  } else if(isPhon){
    if(flags.feminine){
      accent = "acute";
      why = "Herodian notes some -φών forms (e.g. Κολοφών, Τολοφών, κατηφών) are acute ‘as feminines’.";
      conf = "medium";
    } else if(flags.nt){
      accent = "circumflex";
      why = "Rule: masculine compounds in -φων declined with -ντ- take circumflex (e.g. Δημοφῶν).";
      conf = "medium";
    } else {
      accent = "grave";
      why = "Rule: masculine -φων not declined with -ντ- are ‘βαρύνεται’ (shown here as grave on the last syllable).";
      conf = "medium";
    }
  } else if(isChon){
    if(flags.nt){
      accent = "circumflex";
      why = "Named: Πολυσπερχῶν, declined with -ντ-, takes circumflex.";
      conf = "low";
    } else if(flags.month){
      accent = "acute";
      why = "Exception: παχών (month-name) is acute.";
      conf = "medium";
    } else if(flags.feminine && lower.includes("β")){
      accent = "acute";
      why = "Herodian: γλήχων ought to be grave; but if feminine and with β, it is acute (toy toggle).";
      conf = "low";
    } else {
      accent = "grave";
      why = "Rule: disyllabic masculine -χων are ‘βαρύνονται’ unless month-names.";
      conf = "medium";
    }
  } else if(isOn){
    if(flags.nt){
      accent = "circumflex";
      why = "The passage continues: some -ων masculines with final accent and -ντ- declension… (toy extrapolation).";
      conf = "low";
    } else {
      accent = "acute";
      why = "Not enough info here; defaulting to acute on -ών as a toy guess.";
      conf = "low";
    }
  } else {
    accent = null;
    why = "This toy only recognizes endings -φων, -χων, -ων (and a couple named items).";
    conf = "low";
  }

  return {accent, why, conf, base};
}

function confBadge(conf){
  if(conf==="high") return `<span class="badge bOk">high</span>`;
  if(conf==="medium") return `<span class="badge bWarn">medium</span>`;
  return `<span class="badge bBad">low</span>`;
}

function syllabifyRough(word){
  // Very rough: split into chunks ending with a vowel (plus following combining marks).
  const nfd = word.normalize('NFD');
  const chunks = [];
  let cur = "";
  for(let i=0;i<nfd.length;i++){
    const ch = nfd[i];
    cur += ch;
    if(greekVowels.has(ch)){
      // include any following combining marks
      let j=i+1;
      while(j<nfd.length && /[\u0300-\u036f]/.test(nfd[j])){ cur += nfd[j]; j++; }
      i = j-1;
      chunks.push(cur);
      cur = "";
    }
  }
  if(cur) chunks.push(cur);
  return chunks.map(c=>c.normalize('NFC')).filter(x=>x.length);
}

function makeDeclinePlay(word, flags){
  const base = stripAccents(word);
  const lower = base.toLowerCase();
  // playful: show genitive-like with -ντος if -ντ- toggled, else -νος
  if(endsWithAny(lower,["ων"])){
    const stem = base.slice(0, -2); // remove ων
    if(flags.nt) return `${base} → (toy) ${stem}οντος`;
    return `${base} → (toy) ${stem}ωνος`;
  }
  return `${base} → (toy) —`;
}

function renderTargets(word){
  const t = $('#targets');
  t.innerHTML = "";
  const syl = syllabifyRough(word);
  if(!syl.length){
    t.innerHTML = `<div class="mini">(no syllables detected)</div>`;
    return;
  }
  // Offer last 3 syllables as targets: antepenult/penult/ult
  const last = syl.slice(-3);
  const labels = ["antepenult","penult","ult"].slice(3-last.length);
  last.forEach((chunk, idx)=>{
    const lab = labels[idx];
    const btn = document.createElement('button');
    btn.className = 'tgt';
    btn.type = 'button';
    btn.dataset.which = lab;
    btn.textContent = chunk;
    const tag = document.createElement('span');
    tag.className = 'tag';
    tag.textContent = lab;
    btn.appendChild(tag);
    btn.addEventListener('click', ()=>{
      document.querySelectorAll('.tgt').forEach(x=>x.classList.remove('sel'));
      btn.classList.add('sel');
      // Apply accent to last vowel of the chosen chunk by reconstructing word.
      const full = syl.join('');
      const accent = $('#ruleLine').dataset.accent || 'acute';
      // naive: accent last vowel of the whole word if ult; else accent last vowel of penult/antepenult chunk.
      let rebuilt = "";
      const startIndex = syl.length - last.length;
      const targetIndex = startIndex + idx;
      for(let i=0;i<syl.length;i++){
        if(i===targetIndex){
          rebuilt += applyAccentToLastVowel(syl[i], accent);
        } else {
          rebuilt += stripAccents(syl[i]);
        }
      }
      $('#toyForm').textContent = rebuilt;
    });
    t.appendChild(btn);
  });
}

function analyze(){
  const word = $('#inp').value.trim();
  const flags = {
    nt: $('#tglNt').checked,
    feminine: $('#tglFeminine').checked,
    month: $('#tglMonth').checked
  };

  if(!word){
    $('#ruleLine').textContent = '—';
    $('#ruleLine').dataset.accent = '';
    $('#ruleWhy').textContent = 'Type a word to begin.';
    $('#toyForm').textContent = '—';
    $('#decline').textContent = '—';
    $('#targets').innerHTML = '';
    return;
  }

  const g = guessRule(word, flags);
  let shown = stripAccents(word);
  if(g.accent){
    shown = applyAccentToLastVowel(shown, g.accent);
  }

  const accentLabel = g.accent ? g.accent : 'n/a';
  $('#ruleLine').innerHTML = `${shown} <span class="badge">${accentLabel}</span> ${confBadge(g.conf)}`;
  $('#ruleLine').dataset.accent = g.accent || '';
  $('#ruleWhy').textContent = g.why;

  renderTargets(word);
  $('#toyForm').textContent = shown;
  $('#decline').textContent = makeDeclinePlay(word, flags);
}

function loadExample(ex){
  $('#inp').value = ex.w;
  $('#tglNt').checked = !!ex.nt;
  $('#tglFeminine').checked = !!ex.fem;
  $('#tglMonth').checked = !!ex.month;
  analyze();
}

function initChips(){
  const c = $('#chips');
  c.innerHTML = '';
  examples.forEach(ex=>{
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.w;
    b.title = ex.note;
    b.addEventListener('click', ()=>loadExample(ex));
    c.appendChild(b);
  });
}

$('#btnAnalyze').addEventListener('click', analyze);
$('#btnClear').addEventListener('click', ()=>{ $('#inp').value=''; analyze(); });
$('#btnRandom').addEventListener('click', ()=>{
  const ex = examples[Math.floor(Math.random()*examples.length)];
  loadExample(ex);
});
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });
['#tglNt','#tglFeminine','#tglMonth'].forEach(id=>$(id).addEventListener('change', analyze));

initChips();
analyze();
